    double alpha,
    int from,
    bool add,
    bool out,
    bool appliedPose,
  ) {
    return _spine_constraint_timeline1_apply(
      self,
      skeleton,
      lastTime,
      time,
      events,
      alpha,
      from,
      add,
      out,
      appliedPose,
    );
  }

